export const KIND = {"id":68,"example":{"id":"E68","kind":68,"source":"aether","statement":["Write a function `animal_song::verse(unsigned number)` that returns verse number 1 to 3 of a song as a `std::string`, each line ending in `\\n`.","The 3 animals, in order, are cat, dog and cow, and their sounds are meow, woof and moo.","Verse n opens `Animal <n> is the <animal>.` for animal n.","Then, for each animal from animal n back to the first, comes `The <animal> says <sound>.`","Also write `animal_song::verses(unsigned first, unsigned last)`, which returns the verses from first to last, each followed by an empty line.","Also write `animal_song::sing()`, which returns `verses(1, 3)`.","Limits: 1 ≤ number ≤ 3; 1 ≤ first ≤ last ≤ 3."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <array>","#include <string>","","namespace animal_song {","","const std::array<std::string, 3> animals {\"cat\", \"dog\", \"cow\"};","","const std::array<std::string, 3> sounds {\"meow\", \"woof\", \"moo\"};","","std::string verse(unsigned number)","{","    std::string result {\"Animal \" + std::to_string(number)};","    result += \" is the \" + animals[number - 1] + \".\\n\";","    for (unsigned step {number}; step > 0; --step) {","        result += \"The \" + animals[step - 1] + \" says \"","                  + sounds[step - 1] + \".\\n\";","    }","    return result;","}","","std::string verses(unsigned first, unsigned last)","{","    std::string result {};","    for (unsigned number {first}; number <= last; ++number) {","        result += verse(number) + \"\\n\";","    }","    return result;","}","","std::string sing()","{","    return verses(1, 3);","}","","}  // namespace animal_song"],"frame":[0,2,3,5,36],"labels":[{"at":7,"level":1,"text":"Make a table of fixed values."},{"at":7,"level":0,"text":"Make a table outside every function, so each function below reads it."},{"at":9,"level":1,"text":"Make a table of fixed values."},{"at":11,"level":1,"text":"Write a function that builds a new string one piece at a time and gives it back."},{"at":11,"level":0,"text":"Write `unsigned` for an integer that is never below 0."},{"at":13,"level":2,"text":"Start the verse with the line that names the animal."},{"at":15,"level":2,"text":"Add a line for each animal back to the first, with its sound."},{"at":15,"level":0,"text":"Take one from a variable with `--`."},{"at":19,"level":2,"text":"Give back the verse."},{"at":22,"level":1,"text":"Write a function that builds a new string one piece at a time and gives it back."},{"at":24,"level":2,"text":"Start the result as an empty string."},{"at":25,"level":2,"text":"Add each verse, then an empty line."},{"at":28,"level":2,"text":"Give back the result."},{"at":31,"level":1,"text":"Write a function that calls the functions above and gives back the answer."},{"at":33,"level":2,"text":"Give back the verses from the first to the last."}],"blanks":[]}},"trace":{"id":"T68","lines":["#include <array>","#include <iostream>","#include <print>","#include <string>","const std::array<std::string, 3> names {\"one\", \"two\", \"three\"};","void count_down(int number)","{","    for (int step {number}; step > 0; --step) {","        std::println(\"{} and\", names[step - 1]);","    }","    std::println(\"go\");","}","int main()","{","    int number {0};","    std::cin >> number;","    count_down(number);","}"],"columns":["number","step"],"inputs":["2\n","3\n"],"rows":[{"line":15,"values":["0",""]},{"line":16,"values":["2",""]},{"line":8,"values":["2","2"]},{"line":9,"values":["2","2"]},{"line":8,"values":["2","1"]},{"line":9,"values":["2","1"]},{"line":8,"values":["2",""]},{"line":11,"values":["2",""]},{"line":17,"values":["2",""]}],"output":"three and\ntwo and\none and\ngo\n"},"traces":[],"problems":{"68.01":{"id":"68.01","kind":68,"source":"exercism","statement":["Write a function `food_chain::verse(unsigned number)` that returns verse number 1 to 8 of a song as a `std::string`, each line ending in `\\n`.","The 8 animals, in order, are fly, spider, bird, cat, dog, goat, cow and horse. Verse n is about animal n and has these lines:","- `I know an old lady who swallowed a <animal>.` for the verse's animal.","- For animals 2 to 8, its own line: spider `It wriggled and jiggled and tickled inside her.`, bird `How absurd to swallow a bird!`, cat `Imagine that, to swallow a cat!`, dog `What a hog, to swallow a dog!`, goat `Just opened her throat and swallowed a goat!`, cow `I don't know how she swallowed a cow!`, horse `She's dead, of course!`. The horse's verse ends there.","- Then, for each animal from the verse's back to the spider, `She swallowed the <animal> to catch the <animal before it>.`, where the spider as the animal caught is written `spider that wriggled and jiggled and tickled inside her`.","- Last, `I don't know why she swallowed the fly. Perhaps she'll die.`","Also write `food_chain::verses(unsigned first, unsigned last)`, which returns the verses from first to last, each followed by an empty line.","Also write `food_chain::sing()`, which returns `verses(1, 8)`.","Limits: 1 ≤ number ≤ 8; 1 ≤ first ≤ last ≤ 8."],"examples":[{"input":"fly","output":""}],"tests":[{"input":"spider","output":""},{"input":"bird","output":""},{"input":"cat","output":""},{"input":"dog","output":""},{"input":"goat","output":""},{"input":"cow","output":""},{"input":"horse","output":""},{"input":"multiple_verses","output":""},{"input":"the_whole_song","output":""}],"solution":{"lines":["#pragma once","","#include <array>","#include <string>","","namespace food_chain {","","const std::array<std::string, 8> animals {","    \"fly\", \"spider\", \"bird\", \"cat\",","    \"dog\", \"goat\", \"cow\", \"horse\"};","","const std::array<std::string, 8> remarks {","    \"\",","    \"It wriggled and jiggled and tickled inside her.\",","    \"How absurd to swallow a bird!\",","    \"Imagine that, to swallow a cat!\",","    \"What a hog, to swallow a dog!\",","    \"Just opened her throat and swallowed a goat!\",","    \"I don't know how she swallowed a cow!\",","    \"She's dead, of course!\"};","","std::string verse(unsigned number)","{","    const unsigned index {number - 1};","    std::string result {\"I know an old lady who swallowed a \"};","    result += animals[index] + \".\\n\";","    if (index > 0) {","        result += remarks[index] + \"\\n\";","    }","    if (index == 7) {","        return result;","    }","    for (unsigned step {index}; step > 0; --step) {","        result += \"She swallowed the \" + animals[step]","                  + \" to catch the \" + animals[step - 1];","        if (step == 2) {","            result += \" that wriggled and jiggled and tickled\"","                      \" inside her\";","        }","        result += \".\\n\";","    }","    result += \"I don't know why she swallowed the fly.\"","              \" Perhaps she'll die.\\n\";","    return result;","}","","std::string verses(unsigned first, unsigned last)","{","    std::string result {};","    for (unsigned number {first}; number <= last; ++number) {","        result += verse(number) + \"\\n\";","    }","    return result;","}","","std::string sing()","{","    return verses(1, 8);","}","","}  // namespace food_chain"],"frame":[0,2,3,5,60],"labels":[{"at":7,"level":1,"text":"Make a table of fixed values."},{"at":11,"level":1,"text":"Make a table of fixed values."},{"at":21,"level":1,"text":"Write a function that builds a new string one piece at a time and gives it back."},{"at":23,"level":2,"text":"Start the verse with the line that names the animal."},{"at":26,"level":2,"text":"Add the animal's own line, unless it is the fly."},{"at":29,"level":2,"text":"Give back the verse when it is the horse."},{"at":32,"level":2,"text":"Add a line for each animal back to the spider, with the spider's own words after it."},{"at":41,"level":2,"text":"Add the last line and give back the verse."},{"at":46,"level":1,"text":"Write a function that builds a new string one piece at a time and gives it back."},{"at":48,"level":2,"text":"Start the result as an empty string."},{"at":49,"level":2,"text":"Add each verse, then an empty line."},{"at":52,"level":2,"text":"Give back the result."},{"at":55,"level":1,"text":"Write a function that calls the functions above and gives back the answer."},{"at":57,"level":2,"text":"Give back the verses from the first to the last."}],"blanks":[{"line":8,"from":4,"to":9},{"line":12,"from":4,"to":6},{"line":21,"from":18,"to":33},{"line":25,"from":14,"to":27},{"line":26,"from":8,"to":17},{"line":29,"from":8,"to":18},{"line":32,"from":32,"to":40},{"line":43,"from":11,"to":17},{"line":46,"from":19,"to":33},{"line":48,"from":23,"to":25},{"line":50,"from":18,"to":31},{"line":52,"from":11,"to":17},{"line":55,"from":0,"to":11},{"line":57,"from":11,"to":23}]},"fn":{"slug":"food-chain","commit":"8d139cb0","header":"food_chain.h","name":"food_chain_test.cpp","test":"#include \"food_chain.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nusing namespace std;\n\nTEST_CASE(\"fly\") {\n    string expected =\n        \"I know an old lady who swallowed a fly.\\n\"\n        \"I don't know why she swallowed the fly. Perhaps she'll die.\\n\";\n\n    REQUIRE(expected == food_chain::verse(1));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"spider\") {\n    string expected =\n        \"I know an old lady who swallowed a spider.\\n\"\n        \"It wriggled and jiggled and tickled inside her.\\n\"\n        \"She swallowed the spider to catch the fly.\\n\"\n        \"I don't know why she swallowed the fly. Perhaps she'll die.\\n\";\n\n    REQUIRE(expected == food_chain::verse(2));\n}\n\nTEST_CASE(\"bird\") {\n    string expected =\n        \"I know an old lady who swallowed a bird.\\n\"\n        \"How absurd to swallow a bird!\\n\"\n        \"She swallowed the bird to catch the spider that wriggled and jiggled \"\n        \"and tickled inside her.\\n\"\n        \"She swallowed the spider to catch the fly.\\n\"\n        \"I don't know why she swallowed the fly. Perhaps she'll die.\\n\";\n\n    REQUIRE(expected == food_chain::verse(3));\n}\n\nTEST_CASE(\"cat\") {\n    string expected =\n        \"I know an old lady who swallowed a cat.\\n\"\n        \"Imagine that, to swallow a cat!\\n\"\n        \"She swallowed the cat to catch the bird.\\n\"\n        \"She swallowed the bird to catch the spider that wriggled and jiggled \"\n        \"and tickled inside her.\\n\"\n        \"She swallowed the spider to catch the fly.\\n\"\n        \"I don't know why she swallowed the fly. \"\n        \"Perhaps she'll die.\\n\";\n\n    REQUIRE(expected == food_chain::verse(4));\n}\n\nTEST_CASE(\"dog\") {\n    string expected =\n        \"I know an old lady who swallowed a dog.\\n\"\n        \"What a hog, to swallow a dog!\\n\"\n        \"She swallowed the dog to catch the cat.\\n\"\n        \"She swallowed the cat to catch the bird.\\n\"\n        \"She swallowed the bird to catch the spider that wriggled and jiggled \"\n        \"and tickled inside her.\\n\"\n        \"She swallowed the spider to catch the fly.\\n\"\n        \"I don't know why she swallowed the fly. \"\n        \"Perhaps she'll die.\\n\";\n\n    REQUIRE(expected == food_chain::verse(5));\n}\n\nTEST_CASE(\"goat\") {\n    string expected =\n        \"I know an old lady who swallowed a goat.\\n\"\n        \"Just opened her throat and swallowed a goat!\\n\"\n        \"She swallowed the goat to catch the dog.\\n\"\n        \"She swallowed the dog to catch the cat.\\n\"\n        \"She swallowed the cat to catch the bird.\\n\"\n        \"She swallowed the bird to catch the spider that wriggled and jiggled \"\n        \"and tickled inside her.\\n\"\n        \"She swallowed the spider to catch the fly.\\n\"\n        \"I don't know why she swallowed the fly. \"\n        \"Perhaps she'll die.\\n\";\n\n    REQUIRE(expected == food_chain::verse(6));\n}\n\nTEST_CASE(\"cow\") {\n    string expected =\n        \"I know an old lady who swallowed a cow.\\n\"\n        \"I don't know how she swallowed a cow!\\n\"\n        \"She swallowed the cow to catch the goat.\\n\"\n        \"She swallowed the goat to catch the dog.\\n\"\n        \"She swallowed the dog to catch the cat.\\n\"\n        \"She swallowed the cat to catch the bird.\\n\"\n        \"She swallowed the bird to catch the spider that wriggled and jiggled \"\n        \"and tickled inside her.\\n\"\n        \"She swallowed the spider to catch the fly.\\n\"\n        \"I don't know why she swallowed the fly. \"\n        \"Perhaps she'll die.\\n\";\n\n    REQUIRE(expected == food_chain::verse(7));\n}\n\nTEST_CASE(\"horse\") {\n    string expected =\n        \"I know an old lady who swallowed a horse.\\n\"\n        \"She's dead, of course!\\n\";\n\n    REQUIRE(expected == food_chain::verse(8));\n}\n\nTEST_CASE(\"multiple_verses\") {\n    string expected =\n        \"I know an old lady who swallowed a fly.\\n\"\n        \"I don't know why she swallowed the fly. Perhaps she'll die.\\n\"\n        \"\\n\"\n        \"I know an old lady who swallowed a spider.\\n\"\n        \"It wriggled and jiggled and tickled inside her.\\n\"\n        \"She swallowed the spider to catch the fly.\\n\"\n        \"I don't know why she swallowed the fly. Perhaps she'll die.\\n\"\n        \"\\n\";\n\n    REQUIRE(expected == food_chain::verses(1, 2));\n}\n\nTEST_CASE(\"the_whole_song\") {\n    REQUIRE(food_chain::verses(1, 8) == food_chain::sing());\n}\n#endif\n","setup":["string expected = \"I know an old lady who swallowed a fly.\\n\" \"I don't know why she swallowed the fly. Perhaps she'll die.\\n\";"],"calls":[{"call":"food_chain::verse(1)","expected":"expected"}]}},"68.02":{"id":"68.02","kind":68,"source":"aether","statement":["Write a function `fruit_song::verse(unsigned number)` that returns verse number 1 to 4 of a song as a `std::string`, each line ending in `\\n`.","The 4 fruits, in order, are apple, banana, pear and plum, and their colours are red, yellow, green and purple.","Verse n opens `Basket <n> holds:`.","Then, for each fruit from the first to fruit n, comes `- a <colour> <fruit>`.","Verse 4 then ends `The basket is full.`, and each other verse `There is room for more.`","Also write `fruit_song::verses(unsigned first, unsigned last)`, which returns the verses from first to last, each followed by an empty line.","Also write `fruit_song::sing()`, which returns `verses(1, 4)`.","Limits: 1 ≤ number ≤ 4; 1 ≤ first ≤ last ≤ 4."],"examples":[{"input":"verse_two","output":""}],"tests":[{"input":"verse_one","output":""},{"input":"verse_three","output":""},{"input":"verse_four","output":""},{"input":"one_verse","output":""},{"input":"last_two_verses","output":""},{"input":"whole_song","output":""}],"solution":{"lines":["#pragma once","","#include <array>","#include <string>","","namespace fruit_song {","","const std::array<std::string, 4> fruits {","    \"apple\", \"banana\", \"pear\", \"plum\"};","","const std::array<std::string, 4> colours {","    \"red\", \"yellow\", \"green\", \"purple\"};","","std::string verse(unsigned number)","{","    std::string result {\"Basket \" + std::to_string(number)};","    result += \" holds:\\n\";","    for (unsigned index {0}; index < number; ++index) {","        result += \"- a \" + colours[index] + \" \" + fruits[index]","                  + \"\\n\";","    }","    if (number == 4) {","        result += \"The basket is full.\\n\";","    } else {","        result += \"There is room for more.\\n\";","    }","    return result;","}","","std::string verses(unsigned first, unsigned last)","{","    std::string result {};","    for (unsigned number {first}; number <= last; ++number) {","        result += verse(number) + \"\\n\";","    }","    return result;","}","","std::string sing()","{","    return verses(1, 4);","}","","}  // namespace fruit_song"],"frame":[0,2,3,5,43],"labels":[{"at":7,"level":1,"text":"Make a table of fixed values."},{"at":10,"level":1,"text":"Make a table of fixed values."},{"at":13,"level":1,"text":"Write a function that builds a new string one piece at a time and gives it back."},{"at":15,"level":2,"text":"Start the verse with the line that names its number."},{"at":17,"level":2,"text":"Add a line for each fruit from the first to this one, with its colour."},{"at":21,"level":2,"text":"Add the last line and give back the verse."},{"at":29,"level":1,"text":"Write a function that builds a new string one piece at a time and gives it back."},{"at":31,"level":2,"text":"Start the result as an empty string."},{"at":32,"level":2,"text":"Add each verse, then an empty line."},{"at":35,"level":2,"text":"Give back the result."},{"at":38,"level":1,"text":"Write a function that calls the functions above and gives back the answer."},{"at":40,"level":2,"text":"Give back the verses from the first to the last."}],"blanks":[{"line":8,"from":4,"to":11},{"line":11,"from":4,"to":9},{"line":13,"from":18,"to":33},{"line":15,"from":36,"to":58},{"line":17,"from":29,"to":43},{"line":21,"from":8,"to":19},{"line":29,"from":19,"to":33},{"line":31,"from":23,"to":25},{"line":33,"from":18,"to":31},{"line":35,"from":11,"to":17},{"line":38,"from":0,"to":11},{"line":40,"from":11,"to":23}]},"fn":{"slug":"fruit_song","commit":"","header":"fruit_song.h","name":"fruit_song_test.cpp","test":"#include \"fruit_song.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"verse_two\") {\n    REQUIRE(fruit_song::verse(2)\n            == \"Basket 2 holds:\\n- a red apple\\n- a yellow banana\\n\"\n               \"There is room for more.\\n\");\n}\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"verse_one\") {\n    REQUIRE(fruit_song::verse(1)\n            == \"Basket 1 holds:\\n- a red apple\\n\"\n               \"There is room for more.\\n\");\n}\nTEST_CASE(\"verse_three\") {\n    REQUIRE(fruit_song::verse(3)\n            == \"Basket 3 holds:\\n- a red apple\\n- a yellow banana\\n\"\n               \"- a green pear\\nThere is room for more.\\n\");\n}\nTEST_CASE(\"verse_four\") {\n    REQUIRE(fruit_song::verse(4)\n            == \"Basket 4 holds:\\n- a red apple\\n- a yellow banana\\n\"\n               \"- a green pear\\n- a purple plum\\n\"\n               \"The basket is full.\\n\");\n}\nTEST_CASE(\"one_verse\") {\n    REQUIRE(fruit_song::verses(1, 1)\n            == \"Basket 1 holds:\\n- a red apple\\n\"\n               \"There is room for more.\\n\\n\");\n}\nTEST_CASE(\"last_two_verses\") {\n    REQUIRE(fruit_song::verses(3, 4)\n            == fruit_song::verse(3) + \"\\n\" + fruit_song::verse(4)\n                   + \"\\n\");\n}\nTEST_CASE(\"whole_song\") {\n    REQUIRE(fruit_song::sing() == fruit_song::verses(1, 4));\n    REQUIRE(fruit_song::sing().size() == 316);\n}\n#endif\n","setup":[],"calls":[{"call":"fruit_song::verse(2)","expected":"\"Basket 2 holds:\\n- a red apple\\n- a yellow banana\\n\" \"There is room for more.\\n\""}]}}}}
